INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(13606, 'plPL', 'Symbol Frei', 'Zdobycie Symbolu Frei to będzie jedno z trudniejszych zadań, ot co.$B$BWedług Archiwum istota Symbolu jest związana z trzema starszymi sługami Frei: Jasnolistem, Żelaznokonarem i Kamiennokorym. Jeśli któremuś ze starszych stanie się krzywda, Symbol straci swoją moc.$B$BZ drugiej strony, jeśli oszczędzisz starszych, Freja będzie silniejsza, kiedy staniesz z nią do walki.$B$BCo tu dużo gadać, $N. Jesteśmy między młotem a kowadłem.', 'Poszukiwacz Doren w Archiwum w Ulduarze chce, żebyś $gzdobył:zdobyła; Symbol Frei.$B$BWięcej informacji o tym, jak zdobyć Symbol Frei, znajdziesz w Konsoli Archiwum.', '', 'Wróć do Poszukiwacza Dorena w Ulduarze.', '', '', '', '', 0),
(13607, 'plPL', 'Niebiańskie Planetarium', 'Słuchaj no, $gchłopcze:dziewczyno;! Ważą się losy Azeroth.$B$BNasza jedyna szansa to dotrzeć na czas do Niebiańskiego Planetarium, znaleźć tego całego Algalona i nie dopuścić, żeby wysłał jakiekolwiek wiadomości swoim panom tytanom.$B$BOdszukaj Niebiańskie Planetarium i wróć ze wszystkim, czego się dowiesz. Może jeszcze zdążymy przygotować się na przybycie Algalona.', 'Poszukiwacz Doren w Archiwum w Ulduarze chce, żebyś $godnalazł:odnalazła; wejście do Niebiańskiego Planetarium.', 'Wejście do Niebiańskiego Planetarium odnalezione', 'Wróć do Poszukiwacza Dorena w Ulduarze.', '', '', '', '', 0),
(13609, 'plPL', 'Symbol Hodira', 'Nie będzie łatwo zdobyć Symbol Hodira. Nie dość, że trzeba będzie pokonać samego Hodira, to jeszcze musisz to zrobić, zanim zniszczy skrzynię, w której jest Symbol!$B$BJeśli potrzebujesz więcej informacji, sprawdź w Konsoli Archiwum. Ta maszyna ma w sobie więcej wiedzy niż wszystkie biblioteki świata razem wzięte!', 'Poszukiwacz Doren w Archiwum w Ulduarze chce, żebyś $gzdobył:zdobyła; Symbol Hodira.$B$BWięcej informacji o tym, jak zdobyć Symbol Hodira, znajdziesz w Konsoli Archiwum.', '', 'Wróć do Poszukiwacza Dorena w Ulduarze.', '', '', '', '', 0),
(13610, 'plPL', 'Symbol Thorima', 'Thorim nie jest sobą, $N. Padł ofiarą mrocznego wpływu.$B$BJakaś zła istota ukryta pod iluzją podaje się za jego utraconą żonę, Sif.$B$BNie możesz pozwolić, żeby urok tej oszustki go pokonał. Jeśli tak się stanie, miejsce ukrycia jego symbolu może przepaść na zawsze!$B$BTrzeba będzie wbić mu trochę rozumu do głowy, i to szybko.$B$BJak zwykle Konsola Archiwum poda ci wszystkie krwawe szczegóły... nawet te, które ci się nie spodobają.', 'Poszukiwacz Doren w Archiwum w Ulduarze chce, żebyś $gzdobył:zdobyła; Symbol Thorima.$B$BWięcej informacji o tym, jak zdobyć Symbol Thorima, znajdziesz w Konsoli Archiwum.', '', 'Wróć do Poszukiwacza Dorena w Ulduarze.', '', '', '', '', 0),
(13611, 'plPL', 'Symbol Mimirona', 'Mimiron to spryciarz. Całą jego siedzibę oplata jakiś mechanizm samozniszczenia.$B$BNiestety, jeśli chcesz zdobyć jego symbol, musisz się z nim ścigać z czasem. Jeśli potrzebujesz więcej szczegółów, sprawdź w Konsoli Archiwum.', 'Poszukiwacz Doren w Archiwum Ulduaru chce, żebyś $gzdobył:zdobyła; Symbol Mimirona.$B$BWięcej informacji o tym, jak zdobyć Symbol Mimirona, znajdziesz w Konsoli Archiwum.', '', 'Wróć do Poszukiwacza Dorena w Ulduarze.', '', '', '', '', 0),
(13816, 'plPL', 'Heroiczne: Niebiańskie Planetarium', 'Słuchaj no, $gchłopcze:dziewczyno;! Ważą się losy Azeroth.$B$BNasza jedyna szansa to dotrzeć na czas do Niebiańskiego Planetarium, znaleźć tego całego Algalona i nie dopuścić, żeby wysłał jakiekolwiek wiadomości swoim panom tytanom.$B$BOdszukaj Niebiańskie Planetarium i wróć ze wszystkim, czego się dowiesz. Może jeszcze zdążymy przygotować się na przybycie Algalona.', 'Poszukiwaczka Loren w Archiwum w Ulduarze chce, żebyś $godnalazł:odnalazła; wejście do Niebiańskiego Planetarium.', 'Wejście do Niebiańskiego Planetarium odnalezione', 'Wróć do Poszukiwaczki Loren w Ulduarze.', '', '', '', '', 0),
(13821, 'plPL', 'Heroiczne: Symbol Frei', 'Zdobycie Symbolu Frei to będzie jedno z trudniejszych zadań, ot co.$B$BWedług Archiwum istota Symbolu jest związana z trzema starszymi sługami Frei: Jasnolistem, Żelaznokonarem i Kamiennokorym. Jeśli któremuś ze starszych stanie się krzywda, Symbol straci swoją moc.$B$BZ drugiej strony, jeśli oszczędzisz starszych, Freja będzie silniejsza, kiedy staniesz z nią do walki.$B$BCo tu dużo gadać, $N. Jesteśmy między młotem a kowadłem.', 'Poszukiwaczka Loren w Archiwum w Ulduarze chce, żebyś $gzdobył:zdobyła; Symbol Frei.$B$BWięcej informacji o tym, jak zdobyć Symbol Frei, znajdziesz w Konsoli Archiwum.', '', 'Wróć do Poszukiwaczki Loren w Ulduarze.', '', '', '', '', 0),
(13822, 'plPL', 'Heroiczne: Symbol Hodira', 'Nie będzie łatwo zdobyć Symbol Hodira. Nie dość, że trzeba będzie pokonać samego Hodira, to jeszcze musisz to zrobić, zanim zniszczy skrzynię, w której jest Symbol!$B$BJeśli potrzebujesz więcej informacji, sprawdź w Konsoli Archiwum. Ta maszyna ma w sobie więcej wiedzy niż wszystkie biblioteki świata razem wzięte!', 'Poszukiwaczka Loren w Archiwum w Ulduarze chce, żebyś $gzdobył:zdobyła; Symbol Hodira.$B$BWięcej informacji o tym, jak zdobyć Symbol Hodira, znajdziesz w Konsoli Archiwum.', '', 'Wróć do Poszukiwaczki Loren w Ulduarze.', '', '', '', '', 0),
(13823, 'plPL', 'Heroiczne: Symbol Thorima', 'Thorim nie jest sobą, $N. Padł ofiarą mrocznego wpływu.$B$BJakaś zła istota ukryta pod iluzją podaje się za jego utraconą żonę, Sif.$B$BNie możesz pozwolić, żeby urok tej oszustki go pokonał. Jeśli tak się stanie, miejsce ukrycia jego symbolu może przepaść na zawsze!$B$BTrzeba będzie wbić mu trochę rozumu do głowy, i to szybko.$B$BJak zwykle Konsola Archiwum poda ci wszystkie krwawe szczegóły... nawet te, które ci się nie spodobają.', 'Poszukiwaczka Loren w Archiwum w Ulduarze chce, żebyś $gzdobył:zdobyła; Symbol Thorima.$B$BWięcej informacji o tym, jak zdobyć Symbol Thorima, znajdziesz w Konsoli Archiwum.', '', 'Wróć do Poszukiwaczki Loren w Ulduarze.', '', '', '', '', 0),
(13824, 'plPL', 'Heroiczne: Symbol Mimirona', 'Mimiron to spryciarz. Całą jego siedzibę oplata jakiś mechanizm samozniszczenia.$B$BNiestety, jeśli chcesz zdobyć jego symbol, musisz się z nim ścigać z czasem. Jeśli potrzebujesz więcej szczegółów, sprawdź w Konsoli Archiwum.', 'Poszukiwaczka Loren w Archiwum Ulduaru chce, żebyś $gzdobył:zdobyła; Symbol Mimirona.$B$BWięcej informacji o tym, jak zdobyć Symbol Mimirona, znajdziesz w Konsoli Archiwum.', '', 'Wróć do Poszukiwaczki Loren w Ulduarze.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13604, 'plPL', 'Platynowy dysk idealnie pasuje do konsoli. Zaczyna wirować, a białe promienie światła skanują jego zawartość.', 0),
(13606, 'plPL', 'Świetna robota, $N. Jesteśmy o krok bliżej ocalenia Azeroth!', 0),
(13607, 'plPL', 'Zamknięte? No a jakże!$b$bZobaczmy, co powie nam ta kupa złomu...', 0),
(13609, 'plPL', 'Udało ci się! Nie wiem jak, ale ci się udało!', 0),
(13610, 'plPL', 'Nie przestajesz zadziwiać, $N.$b$bJak już będzie po wszystkim, to idziemy razem na kufelek, słyszysz?', 0),
(13611, 'plPL', 'Muszę ci to przyznać, $N. Może nasze szanse nie są najlepsze, ale z twoją pomocą od razu raźniej.', 0),
(13614, 'plPL', 'Trwa weryfikacja.$b$bDostęp do Niebiańskiego Planetarium przyznany. Proszę odebrać klucz.', 0),
(13622, 'plPL', 'Analiza fragmentów... proszę czekać.', 0),
(13816, 'plPL', 'Zamknięte? No a jakże!$b$bDam znać Brannowi... może on coś znajdzie w Archiwum.', 0),
(13817, 'plPL', 'Platynowy dysk idealnie pasuje do konsoli. Zaczyna wirować, a białe promienie światła skanują jego zawartość.', 0),
(13818, 'plPL', 'Trwa weryfikacja.$b$bDostęp do Niebiańskiego Planetarium przyznany. Proszę odebrać klucz.', 0),
(13821, 'plPL', 'Świetna robota, $N. Jesteśmy o krok bliżej ocalenia Azeroth!', 0),
(13822, 'plPL', 'Udało ci się! Nie wiem jak, ale ci się udało!', 0),
(13823, 'plPL', 'Nie przestajesz zadziwiać, $N.$b$bJak już będzie po wszystkim, to idziemy razem na kufelek, słyszysz?', 0),
(13824, 'plPL', 'Muszę ci to przyznać, $N. Może nasze szanse nie są najlepsze, ale z twoją pomocą od razu raźniej.', 0);
