INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(32865, 2, 0, 'plPL', 'Oto potęga burzy i rozpaczy!'),
(32865, 4, 0, 'plPL', 'Czy już żałujecie, że tu wtargnęliście?'),
