INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(11298, 'plPL', '%s ryczy z wściekłością.', '', 0),
(33145, 'plPL', 'Intruzi! Śmiertelnicy, którzy śmiecie przeszkadzać mi w zabawie, zapłacicie... Chwileczkę – ty...', '', 0),
(33148, 'plPL', 'Zuchwałe szczenięta, śmiecie wyzywać mnie na moim własnym piedestale? Sam was zmiażdżę!', '', 0),
(33270, 'plPL', 'Pamiętam cię... w górach... Ale ty... co to ma być? Gdzie ja...', '', 0),
(33274, 'plPL', 'Nieudacznicy! Słabeusze!', '', 0),
(33303, 'plPL', '', 'Oranżerii trzeba bronić!', 0),
(33312, 'plPL', '', 'Freja zaczyna rzucać |cFFFF0000Drżenie ziemi!|r', 0),
(33313, 'plPL', '%s zyskuje Mroźne ciosy!', '', 0),
(33314, 'plPL', '%s zaczyna rzucać Błyskawiczne zamrożenie!', '', 0),
(33323, 'plPL', '%s roztrzaskuje Rzadki skarb Hodira!', '', 0),
(33365, 'plPL', 'Moja cierpliwość się skończyła!', '', 0),
(33370, 'plPL', '', 'Zaczyna rosnąć |cFF00FFFFDar Wiążącej Życie|r!', 0),
(33427, 'plPL', '', 'Pojawili się sojusznicy natury!', 0),
(33471, 'plPL', 'Generał Vezax ryczy i wzbiera mroczną mocą!', '', 0),
(33484, 'plPL', 'Jestem... jestem wolny od jego uścisku... nareszcie.', '', 0),
(33517, 'plPL', '', 'Eonar, twoja sługa potrzebuje pomocy!', 0),
(33518, 'plPL', '', 'Rój żywiołów was pochłonie!', 0),
(33519, 'plPL', '', 'Dzieci, pomóżcie mi!', 0),
(33520, 'plPL', '', 'Starsi, użyczcie mi swojej siły!', 0),
(33524, 'plPL', '', 'Jego władza nade mną słabnie. Znów widzę jasno. Dziękuję wam, bohaterowie.', 0),
(33587, 'plPL', 'Nieopodal zbiera się chmura oparów saronitu!', '', 0),
(33594, 'plPL', 'Opary saronitu gęstnieją i wirują gwałtownie, zlewając się w potworną postać!', '', 0),
(33605, 'plPL', '', 'Zbyt daleko zabłądziliście. Zmarnowaliście zbyt wiele czasu...', 0),
(33632, 'plPL', 'No, no, kto by pomyślał, że będzie mi dane na własne oczy zobaczyć Ulduar! Kiedy Brann poprosił o pomoc w sfinansowaniu tej wyprawy, jakże można było odmówić?!', '', 0),
(33633, 'plPL', 'Kto by pomyślał, że wydostaniemy się z tej parnej dżungli! A teraz jestem głównym inżynierem tej wyprawy.', '', 0),
(33634, 'plPL', 'Co potrafią te machiny oblężnicze?', 'Co potrafią te machiny oblężnicze?', 0),
(33635, 'plPL', 'Te maleństwa może i wyglądają jak złom, ale potrafią pędzić naprzód i rozrzucać wrogów na boki. Taran z przodu dociążyliśmy elektroskopowym hiperkondensatorem, więc może wyładowywać elektryczne wybuchy.$B$BNawet wieżyczkę ulepszyliśmy o rakiety przeciwlotnicze, dzięki czemu ma zdecydowaną przewagę nad tymi przeklętymi niszczycielami.', 'Te maleństwa może i wyglądają jak złom, ale potrafią pędzić naprzód i rozrzucać wrogów na boki. Taran z przodu dociążyliśmy elektroskopowym hiperkondensatorem, więc może wyładowywać elektryczne wybuchy.$B$BNawet wieżyczkę ulepszyliśmy o rakiety przeciwlotnicze, dzięki czemu ma zdecydowaną przewagę nad tymi przeklętymi niszczycielami.', 0),
(33636, 'plPL', 'Nie mamy wiele czasu, przyjaciele! Pomożecie mi przetestować moje najnowsze i największe dzieło. A zanim zmienicie zdanie, pamiętajcie, że jesteście mi to winni po tym bałaganie, jaki narobiliście z XT-002.', '', 0),
(33638, 'plPL', 'CUDOWNIE! Wprost znakomite wyniki! Integralność kadłuba na poziomie 98,9 procent! Ledwie wgniecenie! Idziemy dalej.', '', 0),
(33639, 'plPL', 'Oto VX-001, przeciwpiechotne działo szturmowe! Radzę się ukryć.', '', 0),
(33646, 'plPL', 'Wokół Generała Vezaxa pojawia się bariera z saronitu!', '', 0),
(33647, 'plPL', 'Bariera z saronitu chroniąca Generała Vezaxa migocze i znika!', '', 0),
(33648, 'plPL', 'Mieliśmy szczęście, że znaleźliśmy dość części, żeby znów uruchomić te maleństwa!$BW czym mogę pomóc?', '', 0),
(33649, 'plPL', 'Opowiedz mi o niszczycielach.', 'Opowiedz mi o niszczycielach.', 0),
(33650, 'plPL', 'Te maleństwa miotają ogniem jak nic innego. Dołożyliśmy nawet drugie działo, hak z liną i ręczny system wtrysku paliwa. Jeśli zdobędziesz płynny piryt od mechagnomów, możesz go użyć, żeby ciskać ładunkami wybuchowymi dużej gęstości albo turbodoładować swoją prędkość.\nNiech te smarkacze z Ligi Odkrywców spróbują to przebić!', 'Te maleństwa miotają ogniem jak nic innego. Dołożyliśmy nawet drugie działo, hak z liną i ręczny system wtrysku paliwa. Jeśli zdobędziesz płynny piryt od mechagnomów, możesz go użyć, żeby ciskać ładunkami wybuchowymi dużej gęstości albo turbodoładować swoją prędkość.\nNiech te smarkacze z Ligi Odkrywców spróbują to przebić!', 0),
(33651, 'plPL', 'Dobrze, że się zjawiliście! Żelazne krasnoludy zepchnęły nas aż tutaj i ledwo utrzymujemy linię obrony.\nCo gorsza, zaczęły zasilać swoje magiczne zabezpieczenia. Jeśli wkrótce nie zaatakujemy, zmiotą nas w mgnieniu oka!\nUdało nam się odbudować kilka machin oblężniczych, niszczycieli i motorów po wyprawach Przymierza i Hordy, które były tu przed nami. Ale wszyscy nasi piloci zginęli w ostatnim natarciu.\nMusicie wziąć te pojazdy i szturmować bramy Ulduaru!\nProszę, $n! Jesteście naszą ostatnią nadzieją!', '', 0),
(33652, 'plPL', 'Jesteśmy gotowi. Zaczynajcie szturm!', 'Jesteśmy gotowi. Zaczynajcie szturm!', 0),
(33668, 'plPL', 'Dziękuję, przyjaciele! Wasze wysiłki dostarczyły fantastycznych danych! A teraz, gdzie ja położyłem... a, jest.', '', 0),
(33669, 'plPL', 'Czyż nie jest piękna? Nazywam ją wspaniałą powietrzną jednostką dowodzenia!', '', 0),
(33671, 'plPL', 'Pentarusie, słyszałeś, co $gpowiedział:powiedziała;. Niech twoi magowie zdejmą tarczę i przepuszczą te dzielne dusze!', '', 0),
(33673, 'plPL', 'Oczywiście, Brannie. Za chwilę zdejmiemy tarczę.', '', 0),
(33677, 'plPL', 'Magowie Kirin Toru, na rozkaz Branna zdjąć tarczę! Brońcie tej platformy i naszych sojuszników do ostatniego tchu! Za Dalaran!', '', 0),
(33684, 'plPL', 'Dobra! Ruszamy. Wsiadajcie do maszyn, będę do was mówić stąd przez radio!', '', 0),
(33687, 'plPL', 'Nasi sojusznicy są gotowi. Zdejmijcie tarczę i zróbcie przejście!', '', 0),
(33702, 'plPL', '', 'Słyszałam opowieść czy dwie o strażniku wiedzy w Uldamanie, który pasował do twojego opisu. Czy służysz podobnemu celowi?', 0),
(33703, 'plPL', 'Zostałem skonstruowany, by służyć jako repozytorium kluczowych informacji dotyczących tego kompleksu. Do moich podstawowych funkcji należy przekazywanie stanu frontowych systemów obronnych oraz ocena stanu bytu, do którego uwięzienia zbudowano ten kompleks.', '', 0),
(33704, 'plPL', '', 'Frontowe systemy obronne? Czy jest coś, o czym powinnam powiedzieć Brannowi, zanim pozwoli komukolwiek wejść do kompleksu?', 0),
(33705, 'plPL', 'Dostęp do wnętrza kompleksu jest obecnie ograniczony. Podstawowe stanowiska obronne są aktywne. Systemy dodatkowe są obecnie nieaktywne.', '', 0),
(33706, 'plPL', '', 'Możesz opisać szczegółowo te systemy obronne?', 0),
(33707, 'plPL', 'Wykryto naruszenie kompleksu, włączono obejście zabezpieczeń – zapytanie dozwolone.', '', 0),
(33708, 'plPL', '', 'Rozumiem. Przynajmniej nie musimy się martwić tymi orbitalnymi stanowiskami.', 0),
(33709, 'plPL', '', 'Rhydian, dopilnuj, żeby Brann i arcymag Pentarus natychmiast dowiedzieli się o tych systemach obronnych.', 0),
(33710, 'plPL', '', 'Wspomniałeś też o uwięzionym bycie? Czym jest ten byt i w jakim jest stanie?', 0),
(33711, 'plPL', 'Oznaczenie bytu: Yogg-Saron. Zabezpieczenia naruszone. Stan operacyjny więzienia nieznany. Nie można skontaktować się ze Strażnikami w celu powiadomienia.', '', 0),
(33712, 'plPL', 'Podstawowe stanowiska obronne składają się z żelaznych konstruktów i burzowych latarni, które w razie potrzeby wytwarzają kolejne konstrukty. Systemy dodatkowe składają się z orbitalnych stanowisk obronnych.', '', 0),
(33713, 'plPL', '', 'Yogg-Saron jest tutaj? Zdaje się, że naprawdę będziemy mieć pełne ręce roboty.', 0),
(33716, 'plPL', '', '%s szepcze coś Brannowi.', 0),
(33745, 'plPL', 'Konsola wygląda na prastarą, choć nie widać na niej śladów zniszczenia ani rozkładu. Jedyna szczelina wydaje się pasować do dużych, okrągłych dysków.', '', 0),
(33808, 'plPL', 'Dezaktywacja.', '', 0),
(33833, 'plPL', 'Pokonaliście Żelazne Zgromadzenie i otworzyliście Archiwum! Dobra robota, chłopaki!', '', 0),
(33859, 'plPL', 'W tych salach kryją się tajemnice, które przekraczają nasze najśmielsze marzenia.', '', 0),
(33864, 'plPL', 'Kologarn rzuca Kamienny uścisk!', '', 0),
(33872, 'plPL', 'Rozpoczęcie analizy stanu strażniczki Frei.', '', 0),
(33873, 'plPL', 'Moc strażniczki wzmocniona obecnością starszych sług.', '', 0),
(33874, 'plPL', 'Analiza wzmocnienia Starszego Jasnolista... Trwała obrona obszarowa zasilana wzmocnieniem słonecznym.', '', 0),
(33875, 'plPL', 'Analiza Starszego Kamiennokorego wykazuje obronę dźwiękową zakłócającą używanie magii.', '', 0),
(33876, 'plPL', 'Skanowanie Starszego Żelaznokonara ujawniło roślinne mechanizmy unieruchamiające.', '', 0),
(33877, 'plPL', 'Ponadto analiza wiąże każdego ze starszych ze wzrostem zdolności Frei w zakresie rzucania zaklęć, siły fizycznej lub przyzywania.', '', 0),
(33878, 'plPL', 'Zniszczenie starszych sług spowoduje utratę wzmocnień strażniczki Frei. Jednak trwałe uszkodzenie osoby Frei i jej dobytku, w tym jej symbolu strażniczki, wysoce prawdopodobne.', '', 0),
(33880, 'plPL', 'Rozpoczęcie analizy stanu strażnika Thorima.', '', 0),
(33881, 'plPL', 'Wykryto zewnętrzny wpływ pod iluzoryczną postacią zmarłej towarzyszki Thorima, Sif.', '', 0),
(33882, 'plPL', 'Zakłócenia umysłowe pochodzące od tej istoty niebezpiecznie bliskie wywołania częściowego uszkodzenia pamięci.', '', 0),
(33883, 'plPL', 'Rozpoczęcie analizy stanu strażnika Hodira.', '', 0),
(33884, 'plPL', 'Symbol Hodira znajduje się prawdopodobnie w skrzyni z artefaktami.', '', 0),
(33885, 'plPL', 'Temperament i zachowanie strażnika Hodira wysoce niestabilne. Zniszczenie skrzyni wysoce prawdopodobne w razie przedłużającej się walki.', '', 0),
(33886, 'plPL', 'Sojusznicy obecni na polu bitwy prawdopodobnie zapewnią efekty synergii i skrócą czas walki.', '', 0),
(33887, 'plPL', 'Rozpoczęcie analizy stanu strażnika Mimirona.', '', 0),
(33888, 'plPL', 'Symbol strażnika Mimirona jest powiązany z mechanizmem samozniszczenia połączonym z całymi Korytarzami Pomysłowości.', '', 0),
(33889, 'plPL', 'Spust mechanizmu samozniszczenia nosi kryptonim „Wielki Czerwony Przycisk”; jest dziełem samego Mimirona.', '', 0),
(33890, 'plPL', 'Aby odzyskać symbol Mimirona, należy uruchomić sekwencję samozniszczenia i pokonać Mimirona przed jej zakończeniem.', '', 0),
(33894, 'plPL', 'Wstęp wzbroniony. Niewystarczający poziom dostępu.', '', 0),
(33895, 'plPL', 'Dostęp do Archiwum przyznany. Mechanizmy ochrony przed intruzami wstrzymane.', '', 0),
(33896, 'plPL', 'Rozpoczęcie zapytania. Zabezpieczenie Algalona to automatyczny sygnał alarmowy wysyłany po zgonie Głównego Wyznaczonego.', '', 0),
(33897, 'plPL', 'Potwierdzam. Znacznik czasu zniszczenia Głównego Wyznaczonego Lokena pokrywa się z aktywacją sygnału.', '', 0),
(33898, 'plPL', 'Wyszukiwanie... Zniszczenie Głównego Wyznaczonego uważa się za pierwszy znak ostrzegawczy systemowej awarii planetarnej. Po przybyciu bytu-obserwatora Algalona następuje diagnostyka planetarna, której wynikiem jest jeden z dwóch możliwych sygnałów odpowiedzi. Kod odpowiedzi Alfa, oznaczający „Wszystko w porządku”, oraz kod odpowiedzi Omega, oznaczający planetarne przetworzenie od podstaw.', '', 0),
(33899, 'plPL', 'Rozkład planety i jej żywych organizmów na podstawowe pierwiastki: metale, skały, gazy. Następnie okres odtwarzania każdego pierwiastka zgodnie z pierwotnym planem planety.', '', 0),
(33900, 'plPL', 'Żądanie odrzucone. Kody odpowiedzi są wbudowane w byt-obserwatora Algalona. On jest zarazem posłańcem i wiadomością.', '', 0),
(33901, 'plPL', 'Diagnostyka Algalona ocenia zagrożenie systemowym splugawieniem funkcji życiowych planety przez Przedwiecznego. Obliczanie szansy na kod odpowiedzi Omega...', '', 0),
(33902, 'plPL', 'Dziewięćdziesiąt dziewięć przecinek dziewięć dziewięć procent.', '', 0),
(33903, 'plPL', 'Dziewiątka w okresie, rzecz jasna.', '', 0),
(33904, 'plPL', 'No, to się nazywa piękne znalezisko!', '', 0),
(33905, 'plPL', 'Ja ci pokażę dostęp, ty przeklęta maszyno. Proszę bardzo, jeszcze raz: klucz Norgannona!', '', 0),
(33906, 'plPL', 'Wygląda tak samo jak wszystkie inne archiwa tytanów, które znaleźli moi chłopcy... tylko starsze... i większe.', '', 0),
(33907, 'plPL', 'Chwileczkę, coś tu nie gra! Obok tego migającego światełka... co to za sygnał Algalona?', '', 0),
(33908, 'plPL', 'Główny Wyznaczony? Gdzie ja to już słyszałem? Na brodę mojego dziadka, Loken jest Głównym Wyznaczonym Azeroth. To śmierć Lokena to uruchomiła!', '', 0),
(33909, 'plPL', 'No i? Kto jest po drugiej stronie tego sygnału? Co się stanie?', '', 0),
(33910, 'plPL', 'Planetarne przetworzenie od podstaw? Mów po ludzku, przeklęta maszyno!', '', 0),
(33911, 'plPL', 'Słyszeliście, chłopaki? To tylko koniec świata! No, na co czekasz, zardzewiała maszyno? Wyślij kod odpowiedzi Alfa. Wszystko w porządku! Kolejka na mój koszt!', '', 0),
(33912, 'plPL', 'No dobrze, a czego ten Algalon będzie szukał w tej swojej diagnostyce? Jakie mamy szanse?', '', 0),
(33913, 'plPL', 'Niech to licho, chłopaki. Wygląda na to, że czeka nas walka.', '', 0),
(33932, 'plPL', 'Nowe rozkazy! Otwórz wejście do Niebiańskiego Planetarium.', '', 0),
(33933, 'plPL', 'Czterech strażników? Symbole? Mogłabyś mówić trochę jaśniej, przeklęta maszyno?', '', 0),
(33934, 'plPL', 'To jak mamy zdobyć od nich te symbole? Podejść i grzecznie poprosić?', '', 0),
(33935, 'plPL', 'Powiesz nam, jak te symbole... „odnaruszyć”, prawda?', '', 0),
(33936, 'plPL', 'Latami marzyłem o wędrówce po salach tytanów. Nigdy nie sądziłem, że przyjdzie mi stanąć przeciwko ich dziełom.', '', 0),
(33937, 'plPL', 'Żądanie odrzucone. Dostęp wymaga ręcznej weryfikacji symboli czterech strażników.', '', 0),
(33938, 'plPL', 'Czterej strażnicy Ulduaru: Freja, Thorim, Hodir i Mimiron. Symbole są związane z ich fizyczną i umysłową integralnością. Do uzyskania dostępu do Niebiańskiego Planetarium wymagane są wszystkie cztery symbole.', '', 0),
(33939, 'plPL', 'Analiza stanu strażników. Proszę czekać.', '', 0),
(33940, 'plPL', 'Wykryto splugawienie. Zewnętrzny wpływ przejmuje kontrolę nad strażnikami. Symbole naruszone.', '', 0),
(33941, 'plPL', 'Użycie wystarczającej siły wywoła reset funkcji strażników, usuwając zewnętrzny wpływ.', '', 0),
(33942, 'plPL', 'Co do niezagrożenia symbolom w trakcie tego procesu: istnieje możliwość analizy stanu każdego strażnika i udostępnienia tych informacji po zakończeniu obliczeń.', '', 0),
(33946, 'plPL', 'To prawdziwy zaszczyt pomagać Brannowi w badaniu pradawnego Ulduaru.', '', 0),
(33948, 'plPL', 'Opuśćcie broń! Poddaję się!', '', 0),
(33949, 'plPL', 'Czuję się, jakbym budził się z koszmaru, lecz cienie wciąż zalegają w tym miejscu.', '', 0),
(33950, 'plPL', 'Sif... czy Sif tu była? Niemożliwe – zginęła z ręki mojego brata. Mroczny to był koszmar...', '', 0),
(33951, 'plPL', 'Potrzebuję czasu do namysłu... Wesprę waszą sprawę, jeśli będzie trzeba. Tyle przynajmniej jestem wam winien. Żegnajcie.', '', 0),
(33952, 'plPL', 'Ty! Biesie, nie jesteś moją ukochaną! Precz!', '', 0),
(33953, 'plPL', 'Oto ręka stojąca za całym złem, które spadło na Ulduar, obróciło moje królestwo w ruinę, splugawiło mojego brata i zabiło moją żonę.', '', 0),
(33954, 'plPL', 'A teraz na was, czempioni, spada obowiązek, by pomścić nas wszystkich. Stoi przed wami wielkie zadanie, ale wesprę was, jak tylko zdołam. Musicie zwyciężyć.', '', 0),
(33962, 'plPL', 'Stój spokojnie i patrz w światło!', '', 0),
(33966, 'plPL', 'Wstępna faza testów zakończona. Teraz czas na prawdziwy sprawdzian!', '', 0),
(33991, 'plPL', '', 'Freja rzuca |cFF00FF00Wzmocnione żelazne korzenie!|r', 0),
(34004, 'plPL', '%s zaczyna się przeciążać!', '', 0),
(34033, 'plPL', 'Podziwiajcie jej wspaniałość! Pławcie się w jej chwalebnej, eee, chwale! Przedstawiam wam... V-07-TR-0N!', '', 0),
(34038, 'plPL', 'Analiza strażnika: Freja', 'Analiza strażnika: Freja', 0),
(34039, 'plPL', 'Analiza strażnika: Hodir', 'Analiza strażnika: Hodir', 0),
(34041, 'plPL', 'Analiza strażnika: Thorim', 'Analiza strażnika: Thorim', 0),
(34042, 'plPL', 'Analiza strażnika: Mimiron', 'Analiza strażnika: Mimiron', 0),
(34050, 'plPL', 'Myśleliście, że staniecie naprzeciw legionów śmierci i przeżyjecie?', '', 0),
(34051, 'plPL', 'Opór... skaza śmiertelności.', '', 0),
(34052, 'plPL', 'Wasza klęska była nieunikniona.', '', 0),
(34053, 'plPL', 'Wasza zagłada zwiastuje nową erę cierpienia!', '', 0),
(34054, 'plPL', 'Och, jakież okropności czekają...', '', 0),
(34055, 'plPL', 'Czarna krew Yogg-Sarona płynie w moich żyłach! JESTEM. NIE. DO. ZATRZYMANIA!', '', 0),
(34056, 'plPL', 'Oto teraz: absolutna groza!', '', 0),
(34058, 'plPL', 'Analiza taktyczna zaleca podejście do areny od frontu i rozdzielenie sił, kierując oddział pomocniczy bocznym przejściem na poziomie gruntu. Zmaksymalizuje to szanse na dotarcie do punktu obserwacyjnego Thorima, zanim zewnętrzna istota całkowicie opanuje jego umysł.', '', 0),
(34059, 'plPL', 'Zachowanie skrzyni jest niezbędne do odzyskania symbolu Hodira.', '', 0),
(34061, 'plPL', 'Trwa analiza fragmentów.', '', 0),
(34062, 'plPL', 'Zidentyfikowano obiekt: Val\'anyr, Młot Pradawnych Królów.', '', 0),
(34063, 'plPL', 'Stworzony przez samych tytanów Val\'anyr został przekazany pierwszemu królowi ziemnych, Urelowi Kamiennemu Sercu. Za pomocą tego młota miał on stworzyć i tchnąć życie w resztę swoich braci.', '', 0),
(34064, 'plPL', 'Val\'anyr został strzaskany podczas pierwszej wojny między ziemnymi a żelaznymi krasnoludami. Uważano, że szczątki broni przepadły w tym konflikcie.', '', 0),
(34065, 'plPL', 'Prawdopodobieństwo udanej naprawy zwykłymi środkami dostępnymi na tym świecie jest bliskie zeru. Proszę czekać na analizę środków teoretycznych.', '', 0),
(34066, 'plPL', 'Silnie żrąca substancja, która teoretycznie znajduje się wewnątrz istoty znanej jako Yogg-Saron, tłumaczyłaby upłynnienie saronitu. Zanurzenie w tej substancji mogłoby wystarczyć do ponownego spojenia stopu pochodzenia tytanów.', '', 0),
(34086, 'plPL', 'Wygląda na to, że popełniłem drobny błąd w obliczeniach. Pozwoliłem, by bies w więzieniu splugawił mój umysł i unieważnił moją główną dyrektywę. Wszystkie systemy wydają się już działać. Czysto.', '', 0),
(34107, 'plPL', '', 'Z waszej śmierci zrodzi się nowe życie!', 0),
(34115, 'plPL', 'Pani, ktoś wdarł się do Oranżerii!', '', 0),
(34118, 'plPL', 'Nawóz.', '', 0),
(34119, 'plPL', 'Twoje zwłoki użyźnią glebę.', '', 0),
(34121, 'plPL', 'Pani, jeden z nas poległ!', '', 0),
(34123, 'plPL', 'Śmiertelnicy nie mają tu czego szukać!', '', 0),
(34124, 'plPL', 'Odsyłam cię tam, skąd $gprzybyłeś:przybyłaś;!', '', 0),
(34125, 'plPL', 'PRECZ!', '', 0),
(34126, 'plPL', 'Frejo! Idą po ciebie.', '', 0),
(34129, 'plPL', 'To miejsce będzie waszym cmentarzem.', '', 0),
(34130, 'plPL', 'Co za marnotrawstwo...', '', 0),
(34132, 'plPL', 'Pani, uciekaj! Nie znają litości...', '', 0),
(34135, 'plPL', 'KOL-THARISH!', '', 0),
(34137, 'plPL', 'PONOSISZ PORAŻKĘ!', '', 0),
(34138, 'plPL', 'Wycisnę z ciebie życie!', '', 0),
(34140, 'plPL', 'ZAPOMNIENIE!', '', 0),
(34141, 'plPL', 'Panie, nadchodzą...', '', 0),
(34143, 'plPL', 'To tylko zadrapanie!', '', 0),
(34144, 'plPL', 'Draśnięcie, nic więcej!', '', 0),
(34145, 'plPL', 'Żelazne krasnoludy wychodzą z bunkrów u podstawy filarów, prosto przed wami! Zniszczcie bunkry, a będą musiały się wycofać!', '', 0),
(34147, 'plPL', 'Struktury obronne zasilają cztery generatory. Jeśli je unieszkodliwicie, ostrzał rakietowy ustanie!', '', 0),
(34148, 'plPL', 'Ta wieża zasila Młot Hodira. Podobno ma moc zamieniania w lód całych armii!', '', 0),
(34149, 'plPL', 'Zbliżacie się do wieży Frei. Kryje moc, która w jedną noc zmienia jałowe pustkowia w dżungle tętniące życiem.', '', 0),
(34150, 'plPL', 'Ten generator zasila Spojrzenie Mimirona. W kilka chwil potrafi zamienić ziemię w popiół, a kamień w magmę – nie możemy pozwolić, żeby osiągnął pełną moc!', '', 0),
(34151, 'plPL', 'Ach, wieża Krolmira. Mówią, że moc Thorima została użyta tylko raz... i obróciła w pył cały kontynent.', '', 0),
(34153, 'plPL', 'Wygląda na to, że jesteście blisko stacji naprawczej! Wjedźcie pojazdem na platformę, a powinien zostać automatycznie naprawiony.', '', 0),
(34154, 'plPL', 'Udało się! Przełamaliście obronę Ulduaru. Za kilka chwil zrzucimy...', '', 0),
(34155, 'plPL', 'Co to jest? Uważajcie! Coś się do was zbliża!', '', 0),
(34156, 'plPL', 'Szybko! Manewr wymijający! Manewr wymija...', '', 0),
(34162, 'plPL', '', '%s zaczyna aktywować Dzikiego Obrońcę!', 0),
(34183, 'plPL', 'Ani trochę. Za nic nie mogę pojąć, jak to działa.', 'Ani trochę. Za nic nie mogę pojąć, jak to działa.', 0),
(34184, 'plPL', 'Jakieś postępy?', 'Jakieś postępy?', 0),
(34186, 'plPL', 'Nie poddawaj się. Jeśli nasze podejrzenia są słuszne i to jest teleporter, może się okazać niezwykle przydatny w naszym natarciu.', 'Nie poddawaj się. Jeśli nasze podejrzenia są słuszne i to jest teleporter, może się okazać niezwykle przydatny w naszym natarciu.', 0),
(34187, 'plPL', 'Wiem, wiem... Jeszcze się nie poddałem. Ale nie rób sobie wielkich nadziei, ta technologia mnie przerasta.', 'Wiem, wiem... Jeszcze się nie poddałem. Ale nie rób sobie wielkich nadziei, ta technologia mnie przerasta.', 0),
(34217, 'plPL', '%s zaczyna rzucać Podmuch plazmy!', '', 0),
(34227, 'plPL', '', 'Nasi przyjaciele dzielnie walczyli, Brannie, ale to jeszcze nie koniec.', 0),
(34228, 'plPL', '', 'Żadnych. Podejrzewam, że ma to coś wspólnego z tym olbrzymim mechanicznym konstruktem, którego nasi zwiadowcy dostrzegli przed bramą.', 0),
(34230, 'plPL', '', 'Kirin Tor nie może sobie pozwolić na wydzielenie dodatkowych sił, żeby zmierzyć się z czymś tak wielkim. Może jednak wcale nie będziemy musieli.', 0),
(34232, 'plPL', '', 'Możemy się prześlizgnąć obok nich. Jeśli tylko zniszczymy ten konstrukt przed bramą, powinniśmy dostać się do środka.', 0),
(34234, 'plPL', '', 'Polujemy na Przedwiecznego, Brannie.', 0),
(34239, 'plPL', 'Nie potraficie choćby stawić oporu?', '', 0),
(34241, 'plPL', 'Nie oszczędzajcie się! Zniszczcie ich!', '', 0),
(34244, 'plPL', 'No i po co to zrobiliście? Nie widzieliście napisu „NIE NACISKAJ TEGO PRZYCISKU!”? Jak mamy dokończyć testy z włączonym mechanizmem samozniszczenia?', '', 0),
(34298, 'plPL', 'Ojej! Nie spodziewałem się gości! W warsztacie taki bałagan. Jak mi wstyd.', '', 0),
(34300, 'plPL', 'Mogę to naprawić... a może nie! Rety, co za bałagan...', '', 0),
(34301, 'plPL', 'Fascynujące. Chyba nazywają to „czystym zabójstwem”.', '', 0),
(34302, 'plPL', 'Notatka dla siebie: działo wysoce skuteczne przeciwko ciału.', '', 0),
(34303, 'plPL', 'Ograni!', '', 0),
(34304, 'plPL', 'Stać cię na więcej!', '', 0),
(34305, 'plPL', 'Ojej! Zdaje się, że skończył nam się czas, przyjaciele.', '', 0),
(34314, 'plPL', 'Czy jesteście największymi komarami świata, czy jego największymi bohaterami – wciąż pozostajecie tylko śmiertelnikami.', '', 0),
(34315, 'plPL', 'Litościwe zabójstwo!', '', 0),
(34317, 'plPL', 'Niech wzbiorą burzowe chmury i spuszczą z góry deszcz śmierci!', '', 0),
(34318, 'plPL', 'Moc burzy trwa nadal.', '', 0),
